import React, { useRef, useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { ChevronLeft, ChevronRight } from 'lucide-react';

const CategorySlider = ({ categories }) => {

  const scrollContainerRef = useRef(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const checkScroll = () => {
    if (scrollContainerRef.current) {
      const { scrollLeft, scrollWidth, clientWidth } = scrollContainerRef.current;
      setCanScrollLeft(scrollLeft > 0);
      setCanScrollRight(scrollLeft < scrollWidth - clientWidth);
    }
  };

  useEffect(() => {
    checkScroll();
    window.addEventListener('resize', checkScroll);
    return () => window.removeEventListener('resize', checkScroll);
  }, [categories]);

  const handleScrollRight = () => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollBy({ left: 300, behavior: 'smooth' });
    }
  };

  const handleScrollLeft = () => {
    if (scrollContainerRef.current) {
      scrollContainerRef.current.scrollBy({ left: -300, behavior: 'smooth' });
    }
  };

  return (
    <div className="category-slider">
      <div className="slider-header">
        <h2 className="slider-title">Categories</h2>
        <div className="slider-controls">
          <button className="slider-btn" onClick={handleScrollLeft} disabled={!canScrollLeft}>
            <ChevronLeft size={20} />
          </button>
          <button className="slider-btn" onClick={handleScrollRight} disabled={!canScrollRight}>
            <ChevronRight size={20} />
          </button>
        </div>
      </div>


      <div className="categories-container" ref={scrollContainerRef} onScroll={checkScroll}>
        {categories.map((category) => (
          <Link to={`/products?category=${category.name}`} key={category.id} className="category-item category-link">
            <div className={`category-icon ${category.color}`}>
              <span>{category.icon}</span>
            </div>
            <p className="category-name">{category.name}</p>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default CategorySlider;
